import { useEffect, useState } from 'react'
import { getViolations } from '../api/violations'
import { getUsers } from '../api/users'
import { getZones } from '../api/zones'
import type { User, Zone, ZoneViolation } from '../api/types'

export function ViolationsPage() {
  const [violations, setViolations] = useState<ZoneViolation[]>([])
  const [reps, setReps] = useState<User[]>([])
  const [zones, setZones] = useState<Zone[]>([])

  function refresh() {
    getViolations().then(setViolations).catch(() => {})
  }

  useEffect(() => {
    refresh()
    getUsers('rep').then(setReps).catch(() => {})
    getZones().then(setZones).catch(() => {})
  }, [])

  const repEmailById = new Map(reps.map((rep) => [rep.id, rep.email]))
  const zoneNameById = new Map(zones.map((zone) => [zone.id, zone.name]))

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-xl font-semibold text-gray-900">Zone Violations</h1>
        <button onClick={refresh} className="text-sm text-blue-600 hover:underline">
          Refresh
        </button>
      </div>

      <table className="w-full text-sm bg-white border border-gray-200 rounded">
        <thead>
          <tr className="text-left border-b border-gray-200">
            <th className="p-2">Rep</th>
            <th className="p-2">Zone</th>
            <th className="p-2">Detected</th>
            <th className="p-2">Status</th>
          </tr>
        </thead>
        <tbody>
          {violations.map((violation) => (
            <tr key={violation.id} className="border-b border-gray-100">
              <td className="p-2">{repEmailById.get(violation.rep_id) ?? violation.rep_id}</td>
              <td className="p-2">{zoneNameById.get(violation.zone_id) ?? violation.zone_id}</td>
              <td className="p-2">{new Date(violation.detected_at).toLocaleString()}</td>
              <td className="p-2">
                {violation.resolved_at ? (
                  <span className="text-green-700">Resolved</span>
                ) : (
                  <span className="text-red-700">Open</span>
                )}
              </td>
            </tr>
          ))}
          {violations.length === 0 && (
            <tr>
              <td colSpan={4} className="p-4 text-center text-gray-400">
                No violations recorded.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  )
}

// Hand-written mirrors of backend Pydantic response schemas.
// UUID and ISO-datetime fields are typed as `string` — the backend already
// validates them; the frontend only needs the shape for the compiler.

export interface GeoJSONPolygon {
  type: 'Polygon'
  coordinates: number[][][]
}

export interface Zone {
  id: string
  name: string
  boundary: GeoJSONPolygon
}

export interface ZoneAssignment {
  id: string
  zone_id: string
  rep_id: string
}

export type TaskPriority = 'LOW' | 'MEDIUM' | 'HIGH'

export interface Task {
  id: string
  assigned_to: string
  title: string
  due_date: string | null
  status: string
  priority: string
  external_reference: string | null
  created_at: string
  completed_at: string | null
}

export type GoalMetricType = 'VISIT_COUNT' | 'TASK_COUNT' | 'SALES_VALUE'

export interface Goal {
  id: string
  rep_id: string
  metric_type: string
  target: number
  period_start: string
  period_end: string
  manual_value: number | null
  created_at: string
}

export interface GoalProgress {
  goal_id: string
  rep_id: string
  metric_type: string
  target: number
  achieved: number
  period_start: string
  period_end: string
}

export interface ZoneViolation {
  id: string
  rep_id: string
  zone_id: string
  detected_at: string
  resolved_at: string | null
}

export interface PushSubscription {
  id: string
  manager_id: string
  endpoint: string
  created_at: string
}

export interface VapidPublicKey {
  vapid_public_key: string
}

export interface Ping {
  id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

export interface LatestPing {
  id: string
  rep_id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

export interface User {
  id: string
  email: string
  role: string
}

import { apiFetch } from './client'
import type { ZoneViolation } from './types'

export function getViolations(limit = 50, offset = 0): Promise<ZoneViolation[]> {
  return apiFetch<ZoneViolation[]>(`/api/v1/violations?limit=${limit}&offset=${offset}`)
}

import { useEffect, useState } from 'react'
import { cancelTask, createTask, getTasks } from '../api/tasks'
import { getUsers } from '../api/users'
import type { Task, TaskPriority, User } from '../api/types'

const PRIORITIES: TaskPriority[] = ['LOW', 'MEDIUM', 'HIGH']

export function TasksPage() {
  const [tasks, setTasks] = useState<Task[]>([])
  const [reps, setReps] = useState<User[]>([])
  const [assignedTo, setAssignedTo] = useState('')
  const [title, setTitle] = useState('')
  const [dueDate, setDueDate] = useState('')
  const [priority, setPriority] = useState<TaskPriority>('MEDIUM')

  function refreshTasks() {
    getTasks().then(setTasks).catch(() => {})
  }

  useEffect(() => {
    refreshTasks()
    getUsers('rep').then(setReps).catch(() => {})
  }, [])

  const repEmailById = new Map(reps.map((rep) => [rep.id, rep.email]))

  async function handleCreate(event: React.FormEvent) {
    event.preventDefault()
    if (!assignedTo || !title) return
    await createTask({ assigned_to: assignedTo, title, due_date: dueDate || null, priority })
    setTitle('')
    setDueDate('')
    setPriority('MEDIUM')
    refreshTasks()
  }

  async function handleCancel(taskId: string) {
    await cancelTask(taskId)
    refreshTasks()
  }

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <h1 className="text-xl font-semibold text-gray-900 mb-4">Tasks</h1>

      <form onSubmit={handleCreate} className="flex flex-wrap gap-2 mb-6 bg-white p-4 rounded border border-gray-200">
        <select
          value={assignedTo}
          onChange={(event) => setAssignedTo(event.target.value)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
          required
        >
          <option value="">Assign to…</option>
          {reps.map((rep) => (
            <option key={rep.id} value={rep.id}>
              {rep.email}
            </option>
          ))}
        </select>
        <input
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          placeholder="Title"
          className="border border-gray-300 rounded px-2 py-1 text-sm flex-1 min-w-[150px]"
          required
        />
        <input
          type="date"
          value={dueDate}
          onChange={(event) => setDueDate(event.target.value)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
        />
        <select
          value={priority}
          onChange={(event) => setPriority(event.target.value as TaskPriority)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
        >
          {PRIORITIES.map((value) => (
            <option key={value} value={value}>
              {value}
            </option>
          ))}
        </select>
        <button type="submit" className="px-3 py-1 bg-blue-600 text-white rounded text-sm">
          Create
        </button>
      </form>

      <table className="w-full text-sm bg-white border border-gray-200 rounded">
        <thead>
          <tr className="text-left border-b border-gray-200">
            <th className="p-2">Title</th>
            <th className="p-2">Assignee</th>
            <th className="p-2">Due</th>
            <th className="p-2">Priority</th>
            <th className="p-2">Status</th>
            <th className="p-2"></th>
          </tr>
        </thead>
        <tbody>
          {tasks.map((task) => (
            <tr key={task.id} className="border-b border-gray-100">
              <td className="p-2">{task.title}</td>
              <td className="p-2">{repEmailById.get(task.assigned_to) ?? task.assigned_to}</td>
              <td className="p-2">{task.due_date ?? '—'}</td>
              <td className="p-2">{task.priority}</td>
              <td className="p-2">{task.status}</td>
              <td className="p-2">
                {task.status === 'OPEN' && (
                  <button onClick={() => handleCancel(task.id)} className="text-red-600 hover:underline">
                    Cancel
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { createGoal, getGoalProgress, getGoals } from '../api/goals'
import { getUsers } from '../api/users'
import type { Goal, GoalMetricType, GoalProgress, User } from '../api/types'

const METRIC_TYPES: GoalMetricType[] = ['VISIT_COUNT', 'TASK_COUNT', 'SALES_VALUE']

export function GoalsPage() {
  const [goals, setGoals] = useState<Goal[]>([])
  const [reps, setReps] = useState<User[]>([])
  const [progressByGoalId, setProgressByGoalId] = useState<Record<string, GoalProgress>>({})
  const [repId, setRepId] = useState('')
  const [metricType, setMetricType] = useState<GoalMetricType>('VISIT_COUNT')
  const [target, setTarget] = useState('')
  const [periodStart, setPeriodStart] = useState('')
  const [periodEnd, setPeriodEnd] = useState('')

  function refreshGoals() {
    getGoals().then(setGoals).catch(() => {})
  }

  useEffect(() => {
    refreshGoals()
    getUsers('rep').then(setReps).catch(() => {})
  }, [])

  const repEmailById = new Map(reps.map((rep) => [rep.id, rep.email]))

  async function handleCreate(event: React.FormEvent) {
    event.preventDefault()
    if (!repId || !target || !periodStart || !periodEnd) return
    await createGoal({
      rep_id: repId,
      metric_type: metricType,
      target: Number(target),
      period_start: periodStart,
      period_end: periodEnd,
    })
    setTarget('')
    setPeriodStart('')
    setPeriodEnd('')
    refreshGoals()
  }

  async function handleViewProgress(goalId: string) {
    const progress = await getGoalProgress(goalId)
    setProgressByGoalId((current) => ({ ...current, [goalId]: progress }))
  }

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <h1 className="text-xl font-semibold text-gray-900 mb-4">Goals</h1>

      <form onSubmit={handleCreate} className="flex flex-wrap gap-2 mb-6 bg-white p-4 rounded border border-gray-200">
        <select
          value={repId}
          onChange={(event) => setRepId(event.target.value)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
          required
        >
          <option value="">Rep…</option>
          {reps.map((rep) => (
            <option key={rep.id} value={rep.id}>
              {rep.email}
            </option>
          ))}
        </select>
        <select
          value={metricType}
          onChange={(event) => setMetricType(event.target.value as GoalMetricType)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
        >
          {METRIC_TYPES.map((value) => (
            <option key={value} value={value}>
              {value}
            </option>
          ))}
        </select>
        <input
          type="number"
          value={target}
          onChange={(event) => setTarget(event.target.value)}
          placeholder="Target"
          className="border border-gray-300 rounded px-2 py-1 text-sm w-24"
          required
        />
        <input
          type="date"
          value={periodStart}
          onChange={(event) => setPeriodStart(event.target.value)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
          required
        />
        <input
          type="date"
          value={periodEnd}
          onChange={(event) => setPeriodEnd(event.target.value)}
          className="border border-gray-300 rounded px-2 py-1 text-sm"
          required
        />
        <button type="submit" className="px-3 py-1 bg-blue-600 text-white rounded text-sm">
          Create
        </button>
      </form>

      <table className="w-full text-sm bg-white border border-gray-200 rounded">
        <thead>
          <tr className="text-left border-b border-gray-200">
            <th className="p-2">Rep</th>
            <th className="p-2">Metric</th>
            <th className="p-2">Target</th>
            <th className="p-2">Period</th>
            <th className="p-2">Progress</th>
          </tr>
        </thead>
        <tbody>
          {goals.map((goal) => {
            const progress = progressByGoalId[goal.id]
            return (
              <tr key={goal.id} className="border-b border-gray-100">
                <td className="p-2">{repEmailById.get(goal.rep_id) ?? goal.rep_id}</td>
                <td className="p-2">{goal.metric_type}</td>
                <td className="p-2">{goal.target}</td>
                <td className="p-2">
                  {goal.period_start} – {goal.period_end}
                </td>
                <td className="p-2">
                  {progress ? (
                    `${progress.achieved} / ${progress.target}`
                  ) : (
                    <button onClick={() => handleViewProgress(goal.id)} className="text-blue-600 hover:underline">
                      View
                    </button>
                  )}
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet'
import { useEffect, useState } from 'react'
import { getLatestPings } from '../api/pings'
import { getUsers } from '../api/users'
import { usePolling } from './usePolling'
import type { LatestPing, User } from '../api/types'

const MAP_POLL_INTERVAL_MS = 20_000
const DEFAULT_CENTER: [number, number] = [0, 0]
const DEFAULT_ZOOM = 3

export function MapView() {
  const { data: pings, error } = usePolling<LatestPing[]>(getLatestPings, MAP_POLL_INTERVAL_MS)
  const [reps, setReps] = useState<User[]>([])

  useEffect(() => {
    getUsers('rep').then(setReps).catch(() => {})
  }, [])

  const repEmailById = new Map(reps.map((rep) => [rep.id, rep.email]))

  return (
    <div className="h-screen w-screen">
      {error ? <div className="absolute z-10 bg-red-100 text-red-800 p-2">Failed to load positions</div> : null}
      <MapContainer center={DEFAULT_CENTER} zoom={DEFAULT_ZOOM} className="h-full w-full">
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution="&copy; OpenStreetMap contributors"
        />
        {(pings ?? []).map((ping) => (
          <Marker key={ping.rep_id} position={[ping.latitude, ping.longitude]}>
            <Popup>
              <div>{repEmailById.get(ping.rep_id) ?? ping.rep_id}</div>
              <div className="text-xs text-gray-500">Last seen: {new Date(ping.recorded_at).toLocaleString()}</div>
            </Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  )
}

